    def handle_jsonrpc_request(self, request: Dict[str, Any]) -> Dict[str, Any]:
        req_id = request.get("id")
        method = request.get("method", "")
        params = request.get("params") or {}

        try:
            if method == "initialize":
                return {
                    "jsonrpc": "2.0",
                    "id": req_id,
                    "result": {
                        "protocolVersion": self.PROTOCOL_VERSION,
                        "capabilities": {
                            "tools": {"listChanged": False},
                            "resources": {"subscribe": False},
                            "prompts": {"listChanged": False}
                        },
                        "serverInfo": {
                            "name": "el-aleph-sovereign-mcp",
                            "version": "33.0.0"
                        }
                    }
                }
            elif method == "tools/list":
                import os as _os
                profile = str(params.get("profile") or _os.environ.get("ALEPH_MCP_PROFILE", "full")).lower()
                all_tools = self.get_tools_manifest()
                if profile == "core":
                    core_names = {
                        "aleph_verify_and_repair",
                        "aleph_apply_semantic_patch",
                        "aleph_run_optimality_tournament",
                        "aleph_bitacora_query_hipporag2_ppr",
                        "aleph_bitacora_enforce_pre_turn_gate",
                        "aleph_bitacora_learn_experiential_rule",
                        "aleph_omega_dgm_alphaevolve_self_improve",
                        "aleph_bitacora_vault_status_and_telemetry",
                        "aleph_prove_omega_continual_self_improvement_hipporag2_titans_zero_forgetting_and_bitacora_vault",
                    }
                    filtered_tools = [t for t in all_tools if t["name"] in core_names]
                else:
                    filtered_tools = all_tools
                return {
                    "jsonrpc": "2.0",
                    "id": req_id,
                    "result": {"tools": filtered_tools}
                }
            elif method == "tools/call":
                tool_name = params.get("name")
                args = params.get("arguments") or {}
                tool_output = self._dispatch_mcp_tool(tool_name, args)
                import json
                return {
                    "jsonrpc": "2.0",
                    "id": req_id,
                    "result": {
                        "content": [{"type": "text", "text": json.dumps(tool_output, ensure_ascii=False)}],
                        "isError": False
                    }
                }
            else:
                return {
                    "jsonrpc": "2.0",
                    "id": req_id,
                    "error": {"code": -32601, "message": f"Method not found: {method}"}
                }
        except Exception as ex:
            return {
                "jsonrpc": "2.0",
                "id": req_id,
                "error": {"code": -32603, "message": str(ex)}
            }

    def _dispatch_mcp_tool(self, tool_name: str, args: Dict[str, Any]) -> Dict[str, Any]:
        if not hasattr(self, '_tool_schema_cache'):
            self._tool_schema_cache = {t['name']: t.get('inputSchema', {}).get('properties', {}) for t in self.get_tools_manifest()}
        args = _MCPDefaultArgsDict(args or {}, self._tool_schema_cache.get(tool_name))
        arguments = args
        if tool_name == "aleph_verify_and_repair":
            res = self.engine.verify_and_autorepair_code(
                source_code=args["source_code"],
                use_bitvectors=bool(args.get("use_bitvectors", False))
            )
            return {
                "repaired": res.repaired,
                "original_defect": res.original_defect,
                "counterexample_triggered": res.counterexample_triggered,
                "synthesized_source": res.synthesized_source,
                "final_proof_status": res.final_proof_status,
                "duration_ms": res.duration_ms
            }
        elif tool_name == "aleph_design_render_oracle_audit":
            import sys, os
            dot_aleph_lib = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), ".aleph", "lib")
            if dot_aleph_lib not in sys.path:
                sys.path.insert(0, dot_aleph_lib)
            from aleph_render_oracle import AlephRenderOracle
            html_doc = args.get("html_content", "<!DOCTYPE html><html lang='en'><head><title>Audit</title></head><body><main><h1>Title</h1></main></body></html>")
            oracle = AlephRenderOracle()
            audit_report = oracle.audit_html(html_doc)
            findings = (
                list(audit_report.touch_target_violations)
                + list(audit_report.heading_hierarchy_violations)
                + list(audit_report.contrast_violations)
                + list(audit_report.visual_design_violations)
                + list(audit_report.slop_findings)
            )
            return {
                "score": audit_report.accessibility_score,
                "slop_score": audit_report.slop_score,
                "passes": audit_report.is_passing,
                "finding_count": len(findings),
                "findings": findings,
                "summary": audit_report.summary(),
            }
        elif tool_name == "aleph_visual_stage_synthesizer":
            import sys, os
            dot_aleph_lib = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), ".aleph", "lib")
            if dot_aleph_lib not in sys.path:
                sys.path.insert(0, dot_aleph_lib)
